+    }
+    NS_ENSURE_SUCCESS(rv, rv);
     url.forget(aURI);
     return NS_OK;
   }
diff --git a/mailnews/protocols/exchange/test/unit/test_exchangeRelativeUrls.js b/mailnews/protocols/exchange/test/unit/test_exchangeRelativeUrls.js
